import { CopyToClipboard, COPY_ONLY_CLASS } from "@hunt/copy-to-clipboard";
import { TO_GACHA_UUID } from "@hunt/hunt-data";
import { type TeamHuntState } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import { type ParsedQs } from "qs";
import React, { useEffect, useMemo, useState } from "react";
import { updateQueryParam } from "../../../rounds/query_param_utils";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import GachaBannerSelector from "./components/GachaBannerSelector";
import GachaPageHeader from "./components/GachaPageHeader";
import PuzzlePiece from "./components/PuzzlePiece";
import {
  CASINO_BACKGROUND_STYLE,
  GOLD_BACKGROUND_STYLING,
} from "./gacha_styling";
import {
  type GachaPuzzle,
  type CasinoStateWithUI,
  type SerializedClueContent,
} from "./types";
import useGachaQueryParams, { GACHA_QUERY_KEYS } from "./useGachaQueryParam";

const UnlockAllCluesToggle = ({
  enabled,
  onToggle,
}: {
  enabled: boolean;
  onToggle: () => void;
}) => {
  const modePrefix = enabled ? "Archive Mode:" : "Live Hunt Mode:";
  const modeDetail = enabled
    ? "Showing all clues"
    : "Showing pulled clues only";
  return (
    <button
      type="button"
      onClick={onToggle}
      className="grid grid-cols-[220px_auto] items-center gap-3 text-sm uppercase tracking-wide text-black"
      aria-pressed={enabled}
      aria-label={
        enabled
          ? "Archive Mode: Show pulled clues only"
          : "Live Hunt Mode: Show pulled clues only"
      }
    >
      <span className="text-right leading-tight whitespace-normal">
        <span>{modePrefix}</span>
        <br />
        <span>{modeDetail}</span>
      </span>
      <div
        className={cn(
          "w-[54px] h-[28px] rounded-full flex items-center p-1 cursor-pointer transition-colors shadow-[inset_0_4px_4px_rgba(0,0,0,0.55)]",
          enabled ? "bg-[#C62828]" : "bg-[#569456]",
        )}
      >
        <div
          className={cn(
            "w-[22px] h-[22px] bg-[#B6D0F3] rounded-full transition-all duration-200 ease-in-out",
            enabled ? "translate-x-[24px]" : "translate-x-0",
          )}
        />
      </div>
    </button>
  );
};

type GachaGalleryContentProps = {
  items:
    | {
        item: SerializedClueContent;
        originalIdx: number;
      }[]
    | null;
  puzzle1: GachaPuzzle | undefined;
  puzzle2: GachaPuzzle | undefined;
};

function GachaGalleryContent({
  items,
  puzzle1,
  puzzle2,
}: GachaGalleryContentProps) {
  return (
    <div className="flex flex-col gap-4 max-w-5xl pt-1">
      {(puzzle1?.state === "unlocked" || puzzle2?.state === "unlocked") && (
        <div className="flex justify-center gap-4">
          {puzzle1?.state === "unlocked" && <PuzzlePiece puzzle={puzzle1} />}
          {puzzle2?.state === "unlocked" && <PuzzlePiece puzzle={puzzle2} />}
          <br className={COPY_ONLY_CLASS} />
        </div>
      )}
      {!!items?.length && (
        <div className="flex flex-wrap justify-center gap-2">
          {items?.map(({ item, originalIdx }) => {
            return (
              <div
                key={originalIdx}
                className="relative w-fit h-fit group/cell-clue-content"
              >
                <div
                  dangerouslySetInnerHTML={{
                    __html: item.component,
                  }}
                />
                {/* Only show individual copy-to-clipboard for Cells banner since it's helpful to be able to use a whiteboarding tool. */}
                {item.banner_slug === "cells" && (
                  <CopyToClipboard
                    contentId={`${item.clue_id}-content`}
                    variant="custom"
                    className="absolute top-1 left-1 w-fit hidden group-hover/cell-clue-content:block"
                    iconClassName="w-10 min-w-10"
                    tooltipClassname="max-w-52"
                    tooltipBeforeCopy="Copy as image for ease of pasting into whiteboarding tools like Excalidraw."
                    tooltipSide="bottom"
                    mode="image"
                  />
                )}
              </div>
            );
          })}
        </div>
      )}
      {!items?.length &&
        puzzle1?.state !== "unlocked" &&
        puzzle2?.state !== "unlocked" && (
          <span className="text-2xl text-black font-bold my-6">
            You have not pulled any pieces yet.
          </span>
        )}
    </div>
  );
}

type GachaGalleryProps = {
  state: CasinoStateWithUI;
  teamState: TeamHuntState;
  queryParams: ParsedQs | URLSearchParams;
  clueComponents: SerializedClueContent[];
};

function GachaGallery({
  state,
  queryParams,
  clueComponents,
}: GachaGalleryProps) {
  const { banner } = useGachaQueryParams(queryParams);
  const [selectedBannerSlug, setSelectedBannerSlug] = useState(banner || "");
  const [unlockAllClues, setUnlockAllClues] = useState(false);
  const [allClueComponents, setAllClueComponents] = useState<
    SerializedClueContent[] | null
  >(null);

  const availableBanners = useMemo(() => {
    return unlockAllClues
      ? state.banners
      : state.banners.filter((currBanner) => currBanner.state === "unlocked");
  }, [state.banners, unlockAllClues]);
  const selectorState = useMemo(() => {
    if (!unlockAllClues) {
      return state;
    }
    return {
      ...state,
      banners: state.banners.map((bannerData) => ({
        ...bannerData,
        state: "unlocked" as const,
      })),
      banner_progress: state.banner_progress.map((progress) => ({
        ...progress,
        num_clues_pulled: progress.total_clues,
      })),
    };
  }, [state, unlockAllClues]);

  const allClueTargets = useMemo(() => {
    const bannerSlugs = new Set(
      state.banners.map((currBanner) => currBanner.slug),
    );
    return Object.entries(TO_GACHA_UUID)
      .filter(([subpuzzleSlug]) => {
        const [bannerSlug] = subpuzzleSlug.split("-");
        return bannerSlugs.has(bannerSlug);
      })
      .map(([subpuzzleSlug, clueId]) => {
        const [bannerSlug] = subpuzzleSlug.split("-");
        return { clue_id: clueId, banner_slug: bannerSlug };
      });
  }, [state.banners]);

  useEffect(() => {
    if (
      selectedBannerSlug &&
      availableBanners.some(
        (currBanner) => currBanner.slug === selectedBannerSlug,
      )
    ) {
      updateQueryParam(GACHA_QUERY_KEYS.BANNER, selectedBannerSlug ?? "", true);
    } else {
      if (availableBanners.length > 0) {
        const firstBannerSlug = availableBanners[0].slug;
        setSelectedBannerSlug(firstBannerSlug);
        updateQueryParam(GACHA_QUERY_KEYS.BANNER, firstBannerSlug, true);
      }
    }
  }, [availableBanners, selectedBannerSlug]);

  useEffect(() => {
    if (!unlockAllClues || !IS_STATIC_SITE) return;
    if (allClueComponents !== null) return;
    let cancelled = false;
    void (async () => {
      const results = await Promise.all(
        allClueTargets.map(async (clue) => {
          try {
            const response = await fetch(
              `/rounds/fates_thread_casino/clue/${clue.clue_id}/raw`,
            );
            if (!response.ok) {
              return null;
            }
            const component = await response.text();
            return {
              clue_id: clue.clue_id,
              banner_slug: clue.banner_slug,
              component,
            } as SerializedClueContent;
          } catch {
            return null;
          }
        }),
      );
      if (!cancelled) {
        setAllClueComponents(
          results.filter(Boolean) as SerializedClueContent[],
        );
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [allClueComponents, allClueTargets, unlockAllClues]);

  const selectedBanner = useMemo(() => {
    return state.banners.find(
      (currBanner) => currBanner.slug === selectedBannerSlug,
    );
  }, [selectedBannerSlug, state.banners]);

  const currentGalleryItems = useMemo(() => {
    if (!selectedBanner) {
      return null;
    }
    const sourceClues =
      unlockAllClues && allClueComponents !== null
        ? allClueComponents
        : clueComponents;
    return sourceClues
      .map((item, originalIdx) => ({ item, originalIdx }))
      .filter(({ item }) => {
        // Filter so that only the current banner's pieces are showing.
        return item.banner_slug === selectedBanner.slug;
      });
  }, [allClueComponents, clueComponents, selectedBanner, unlockAllClues]);

  const numChips = useMemo(() => {
    return state.available_pulls ?? 0;
  }, [state.available_pulls]);

  return (
    <div
      className="flex flex-col min-h-screen pt-16 w-full pb-8 overflow-x-auto"
      style={CASINO_BACKGROUND_STYLE}
    >
      <div className="flex flex-col items-center min-w-[660px] mx-auto px-8">
        <GachaPageHeader
          title="Gallery"
          selectedBanner={selectedBannerSlug}
          numChips={numChips}
        >
          <GachaBannerSelector
            selectedBanner={selectedBannerSlug}
            onBannerChange={(newBannerSlug: string) => {
              setSelectedBannerSlug(newBannerSlug);
              const url = new URL(window.location.href);
              url.searchParams.set(GACHA_QUERY_KEYS.BANNER, newBannerSlug);
              window.history.replaceState({}, "", url.toString());
            }}
            state={selectorState}
            auxControl={
              IS_STATIC_SITE ? (
                <UnlockAllCluesToggle
                  enabled={unlockAllClues}
                  onToggle={() => {
                    setUnlockAllClues((prev) => !prev);
                  }}
                />
              ) : undefined
            }
          />
        </GachaPageHeader>
        <div
          id="cash-gallery-content"
          className={cn(
            "cash-gallery-content mb-2 w-[90vw] min-w-[660px] max-w-5xl text-center p-4 rounded-lg",
            GOLD_BACKGROUND_STYLING,
          )}
        >
          <GachaGalleryContent
            items={currentGalleryItems}
            puzzle1={selectedBanner?.puzzle1}
            puzzle2={selectedBanner?.puzzle2}
          />
        </div>
        <div className="ml-48 mt-4">
          <CopyToClipboard
            contentId="cash-gallery-content"
            tooltipBeforeCopy="Click to copy all current clues for ease of pasting into Google Sheets or Excel."
          />
        </div>
      </div>
    </div>
  );
}

export default GachaGallery;
