import { type TeamHuntState } from "@hunt/public-client";
import React, { useEffect, useState } from "react";
import { hydrateRoot } from "react-dom/client";
import useDataset from "../client/useDataset";
import { useSolvedPuzzlesState } from "../components/puzzleSolveLocalState";
import GachaGallery from "../rounds/dimensions/gacha/GachaGallery";
import { mergeCasinoState } from "../rounds/dimensions/gacha/clientUtils";
import {
  buildLocalCasinoState,
  buildLocalGalleryClues,
} from "../rounds/dimensions/gacha/gachaLocalState";
import type {
  CasinoStateWithUI,
  SerializedClueContent,
} from "../rounds/dimensions/gacha/types";
import { useGachaLocalState } from "../rounds/dimensions/gacha/useGachaLocalState";
import { IS_STATIC_SITE } from "../utils/staticSite";
import { ErrataDataProvider } from "./ErrataProvider";

const GachaGalleryManager = ({
  initialCasinoState,
  initialTeamState,
  queryParams,
  initialClueComponents,
}: {
  initialCasinoState: CasinoStateWithUI;
  initialTeamState: TeamHuntState;
  queryParams: URLSearchParams;
  initialClueComponents: SerializedClueContent[];
}) => {
  const isStaticSite = IS_STATIC_SITE;
  // Use websocket data for real-time updates
  const teamState = useDataset("team_state", undefined, initialTeamState);
  const wsState = useDataset("fates_thread_casino", undefined, {
    epoch: initialCasinoState.epoch,
    available_pulls: initialCasinoState.available_pulls,
    num_solves: initialCasinoState.num_solves,
    banner_progress: initialCasinoState.banner_progress,
  });

  const [state, setState] = useState<CasinoStateWithUI>(initialCasinoState);
  const [clueComponents, setClueComponents] = useState<SerializedClueContent[]>(
    initialClueComponents,
  );
  const { solvedMap } = useSolvedPuzzlesState();
  const { localState } = useGachaLocalState();

  useEffect(() => {
    if (isStaticSite) return;
    setState((currentState) => mergeCasinoState(wsState, currentState));
  }, [isStaticSite, wsState]);

  useEffect(() => {
    if (!isStaticSite || !localState) return;
    const nextState = buildLocalCasinoState({
      teamState,
      localState,
      solvedMap,
    });
    setState(nextState);
  }, [isStaticSite, localState, solvedMap, teamState]);

  useEffect(() => {
    if (!isStaticSite || !localState) return;
    let cancelled = false;
    const clues = buildLocalGalleryClues(localState);
    if (clues.length === 0) {
      setClueComponents([]);
      return;
    }
    const fetchClues = async () => {
      const results = await Promise.all(
        clues.map(async (clue) => {
          try {
            const response = await fetch(
              `/rounds/fates_thread_casino/clue/${clue.clue_id}/raw`,
            );
            if (!response.ok) {
              return null;
            }
            const component = await response.text();
            return {
              clue_id: clue.clue_id,
              banner_slug: clue.banner_slug,
              component,
            } as SerializedClueContent;
          } catch {
            return null;
          }
        }),
      );
      if (!cancelled) {
        setClueComponents(results.filter(Boolean) as SerializedClueContent[]);
      }
    };
    void fetchClues();
    return () => {
      cancelled = true;
    };
  }, [isStaticSite, localState]);

  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GachaGallery
        state={state}
        teamState={teamState}
        queryParams={queryParams}
        clueComponents={clueComponents}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("fates-thread-casino-gallery-root");
if (elem) {
  const {
    initialTeamState: teamState,
    initialCasinoState: fatesThreadCasinoState,
    initialClueComponents: clueComponents,
  } = window as unknown as {
    initialTeamState: TeamHuntState;
    initialCasinoState: CasinoStateWithUI;
    initialClueComponents: SerializedClueContent[];
  };
  const queryParams = new URLSearchParams(window.location.search);

  hydrateRoot(
    elem,
    <GachaGalleryManager
      initialCasinoState={fatesThreadCasinoState}
      initialTeamState={teamState}
      queryParams={queryParams}
      initialClueComponents={clueComponents}
    />,
  );
} else {
  console.error(
    "Could not mount Fate's Thread Casino Gallery because #fates-thread-casino-gallery-root was nowhere to be found",
  );
}
